#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

template <typename scalar_t>
__global__ void avg_pool_forward_kernel(
    const scalar_t* __restrict__ input,
    scalar_t* __restrict__ output,
    const int batch,
    const int channels,
    const int input_len,
    const int output_len,
    const int kernel_size,
    const int stride,
    const int padding)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch * channels * output_len;
    if (idx >= total) return;

    int out_pos = idx % output_len;
    int tmp = idx / output_len;
    int c = tmp % channels;
    int b = tmp / channels;

    int start = out_pos * stride - padding;
    float sum = 0.0f;
    for (int k = 0; k < kernel_size; ++k) {
        int in_pos = start + k;
        if (in_pos >= 0 && in_pos < input_len) {
            int input_idx = b * channels * input_len + c * input_len + in_pos;
            sum += __half2float(input[input_idx]);
        }
    }
    float avg = sum / static_cast<float>(kernel_size);
    int out_idx = b * channels * output_len + c * output_len + out_pos;
    output[out_idx] = __float2half(avg);
}

void avg_pool_forward(
    torch::Tensor input,
    torch::Tensor output,
    const int kernel_size,
    const int stride,
    const int padding)
{
    const int batch = input.size(0);
    const int channels = input.size(1);
    const int input_len = input.size(2);
    const int output_len = output.size(2);

    const int threads = 256;
    const int total = batch * channels * output_len;
    const int blocks = (total + threads - 1) / threads;

    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "avg_pool_forward_cuda", ([&] {
        avg_pool_forward_kernel<scalar_t><<<blocks, threads>>>(
            input.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            batch,
            channels,
            input_len,
            output_len,
            kernel_size,
            stride,
            padding);
    }));

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA error in avg_pool_forward: %s\\n", cudaGetErrorString(err));
    }
}
'''

