class _AvgPool1dFunction(torch.autograd.Function):
    @staticmethod
    def forward(ctx, input, kernel_size, stride, padding):
        batch, channels, input_len = input.shape
        output_len = (input_len + 2 * padding - kernel_size) // stride + 1
